import copy
from collections.abc import Mapping


class MemoryCatalog:
    def __init__(self, collections):
        if not isinstance(collections, Mapping):
            raise TypeError("collections must be a mapping")
        prepared = {}
        for name, source_rows in collections.items():
            if not isinstance(name, str):
                raise TypeError("collection names must be strings")
            if not name:
                raise ValueError("collection names must not be empty")
            if isinstance(source_rows, (str, bytes)):
                raise TypeError("rows must be an iterable of mappings")
            try:
                rows = list(source_rows)
            except TypeError as exc:
                raise TypeError("rows must be iterable") from exc
            for row in rows:
                if not isinstance(row, Mapping):
                    raise TypeError("each row must be a mapping")
                if any(not isinstance(key, str) for key in row):
                    raise TypeError("row keys must be strings")
            prepared[name] = copy.deepcopy(rows)
        self._collections = prepared

    def _rows(self, name):
        if not isinstance(name, str):
            raise TypeError("collection name must be a string")
        if not name:
            raise ValueError("collection name must not be empty")
        if name not in self._collections:
            raise KeyError(name)
        return self._collections[name]

    def collection_names(self):
        return sorted(self._collections)

    def fields(self, name):
        rows = self._rows(name)
        return tuple(rows[0]) if rows else ()

    def select(self, name, filters=None):
        rows = self._rows(name)
        if filters is None:
            filters = {}
        if not isinstance(filters, Mapping):
            raise TypeError("filters must be a mapping or None")
        if any(not isinstance(key, str) for key in filters):
            raise TypeError("filter keys must be strings")
        matches = [row for row in rows if all(row.get(key) == value for key, value in filters.items())]
        return matches


class ResidentCatalog(MemoryCatalog):
    def residents_in_zone(self, zone):
        if not isinstance(zone, str):
            raise TypeError("zone must be a string")
        return self.select("residents", {"zone": zone})


class WorkerCatalog(MemoryCatalog):
    def workers_with_role(self, role):
        if not isinstance(role, str):
            raise TypeError("role must be a string")
        return self.select("workers", {"role": role})

